  if (!validParts(y, mo, d, h, mi, sec)) throw new Error('Instant is not a real date-time')
  let offsetMin = 0
  if (m[8] !== 'Z') {
    const oh = Number(m[10])
    const om = Number(m[11])
    if (oh > 23 || om > 59) throw new Error('Invalid offset')
    offsetMin = (m[9] === '-' ? -1 : 1) * (oh * 60 + om)
  }
