      })
      .catch(() => {
        if (cancelled) return;
        setFailed(true);
        toast.error("Could not load your tenancy");
      });
    return () => {
      cancelled = true;
    };
  }, [reloadKey]);

  function reload() {
    setData(null);
    setFailed(false);
    setReloadKey((k) => k + 1);
  }

  if (failed) {
    return (
      <Card className="max-w-md">
        <CardHeader>
          <CardTitle>Something went wrong</CardTitle>
          <CardDescription>Your tenancy could not be loaded.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button onClick={reload}>Try again</Button>
        </CardContent>
      </Card>
    );
  }

  if (!data || !now) return <PortalSkeleton />;

  if (data.tenants.length === 0) {
    return (
      <Card className="max-w-md">
        <CardHeader>
          <CardTitle>No tenancy found</CardTitle>
          <CardDescription>This account is not linked to a tenant profile.</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-semibold tracking-tight">My tenancy</h1>
        <Button variant="outline" onClick={reload}>
          Refresh
        </Button>
      </div>

      {data.tenants.map((t) => (
        <Card key={t.id}>
          <CardHeader>
            <CardTitle>{t.full_name}</CardTitle>
            <CardDescription>{t.email}</CardDescription>
          </CardHeader>
          <CardContent>
            <PhoneForm
              tenantId={t.id}
              phone={t.phone}
              onSaved={(phone) =>
                setData((d) => (d ? { ...d, tenants: d.tenants.map((x) => (x.id === t.id ? { ...x, phone } : x)) } : d))
              }
            />
          </CardContent>
        </Card>
      ))}

      {data.leases.length === 0 ? (
        <Card className="max-w-md">
          <CardHeader>
            <CardTitle>No leases</CardTitle>
            <CardDescription>You do not have a lease yet.</CardDescription>
          </CardHeader>
        </Card>
      ) : (
        data.leases.map((lease) => (
          <LeaseSection
            key={lease.id}
            lease={lease}
            invoices={data.invoices.filter((i) => i.leaseId === lease.id)}
            payments={data.payments.filter((p) => p.leaseId === lease.id)}
            paidByInvoice={data.paidByInvoice}
            now={now}
          />
        ))
      )}
    </div>
  );
}

function PortalSkeleton() {
  return (
    <div className="flex flex-col gap-6" aria-busy="true" aria-label="Loading your tenancy">
      <Skeleton className="h-8 w-48" />
      <Skeleton className="h-32 w-full" />
      <Skeleton className="h-64 w-full" />
      <Skeleton className="h-48 w-full" />
    </div>
  );
}

import { TenantPortal } from "@/components/tenant/tenant-portal";

export const metadata = { title: "My tenancy" };

// The (app) layout redirects visitors without a session. Data is read in the browser with supabase-js,
// so Postgres RLS (not this page) decides what the signed-in tenant sees.
export default function TenantPage() {
  return <TenantPortal />;
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { RefreshButton } from "@/components/tenant/refresh-button";
import { Badge } from "@/components/ui/badge";
import { buttonVariants } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/errors";
import { formatSen } from "@/lib/money";
import { createClient } from "@/lib/supabase/server";
import { cn } from "@/lib/utils";
import { getGatewayBill, type GatewayBillDto } from "@/server/services/gateway";

export const metadata = { title: "Payment status" };
export const dynamic = "force-dynamic";

const MESSAGE: Record<GatewayBillDto["status"], string> = {
  pending: "We are waiting for the gateway to confirm your payment.",
  paid: "Payment received. Thank you.",
  failed: "The payment failed. You can start a new payment from your tenancy page.",
};

// R31: strictly read-only. Only the gateway webhook settles a bill, so the `paid` query parameter is never
// read here; the status shown is whatever the database says.
export default async function PaymentReturnPage({
  searchParams,
}: {
  searchParams: Promise<{ bill_id?: string | string[] }>;
}) {
  const { bill_id } = await searchParams;
  const billId = Array.isArray(bill_id) ? bill_id[0] : bill_id;

  const supabase = await createClient();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) redirect("/login");

  let bill: GatewayBillDto | null = null;
  if (billId) {
    try {
      bill = await getGatewayBill({ userId: data.user.id }, billId);
    } catch (e) {
      // Unknown, malformed or someone else's bill all look the same (R38); anything else is a real error.
      if (!(e instanceof ApiError && e.status === 404)) throw e;
    }
  }

  return (
    <Card className="max-w-lg">
      <CardHeader>
        <CardTitle>Payment status</CardTitle>
        {bill && <CardDescription>The status below is read from our records.</CardDescription>}
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        {bill ? (
          <>
            <div className="flex items-center gap-2">
              <Badge variant={bill.status === "paid" ? "default" : bill.status === "failed" ? "destructive" : "secondary"}>
                {bill.status === "paid" ? "Paid" : bill.status === "failed" ? "Failed" : "Pending"}
              </Badge>
              <p className="text-sm" data-testid="bill-status-message">
                {MESSAGE[bill.status]}
              </p>
            </div>
            <dl className="grid grid-cols-[max-content_1fr] gap-x-4 gap-y-1 text-sm">
              <dt className="text-muted-foreground">Bill id</dt>
              <dd className="font-mono break-all">{bill.billId}</dd>
              <dt className="text-muted-foreground">Amount</dt>
              <dd>{formatSen(bill.amountSen)}</dd>
            </dl>
          </>
        ) : (
          <p className="text-sm" data-testid="bill-status-message">
            Bill not found
          </p>
        )}
        <div className="flex flex-wrap gap-2">
          {bill?.status === "pending" && <RefreshButton />}
          <Link href="/tenant" className={cn(buttonVariants({ variant: "outline" }))}>
            Back to my tenancy
          </Link>
        </div>
      </CardContent>
    </Card>
  );
}
